import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 n_elem
)
{
    .reg .pred  %p_done, %p_hi, %p_lo;
    .reg .b32   %r_idx, %r_n, %r_tid, %r_cta, %r_ntid, %r_grid, %r_stride;
    .reg .b64   %rd_in, %rd_out, %rd_in_g, %rd_out_g, %rd_off, %rd_addr_in, %rd_addr_out;
    .reg .f32   %fx, %f2x, %flog2e, %fy, %fnum, %fden, %frcpden, %fres, %fth, %fnegth;

    // Load parameters
    ld.param.u64 %rd_in,  [in_ptr];
    ld.param.u64 %rd_out, [out_ptr];
    ld.param.u32 %r_n,    [n_elem];

    // Thread and grid info
    mov.u32 %r_tid,  %tid.x;
    mov.u32 %r_cta,  %ctaid.x;
    mov.u32 %r_ntid, %ntid.x;
    mov.u32 %r_grid, %nctaid.x;

    // Global linear index
    mad.lo.u32 %r_idx, %r_cta, %r_ntid, %r_tid;

    // Stride = blockDim.x * gridDim.x
    mul.lo.u32 %r_stride, %r_ntid, %r_grid;

    // Convert pointers to global space
    cvta.to.global.u64 %rd_in_g,  %rd_in;
    cvta.to.global.u64 %rd_out_g, %rd_out;

    // Constants
    mov.f32 %flog2e, 1.44269504;  // log2(e)
    mov.f32 %fth,    10.0;        // threshold to avoid overflow
    neg.f32 %fnegth, %fth;

LOOP:
    setp.ge.u32 %p_done, %r_idx, %r_n;
    @%p_done bra DONE;

    // Compute address for current index
    mul.wide.u32 %rd_off, %r_idx, 4;
    add.s64 %rd_addr_in,  %rd_in_g,  %rd_off;
    add.s64 %rd_addr_out, %rd_out_g, %rd_off;

    // Load input
    ld.global.f32 %fx, [%rd_addr_in];

    // Check thresholds
    setp.gt.f32 %p_hi, %fx, %fth;
    setp.lt.f32 %p_lo, %fx, %fnegth;

    // Default path: tanh via exp(2x) = 2^(2x * log2(e))
    add.f32 %f2x, %fx, %fx;                 // 2x
    mul.rn.f32 %f2x, %f2x, %flog2e;         // 2x * log2(e)
    ex2.approx.f32 %fy, %f2x;               // y = exp(2x)
    add.f32 %fden, %fy, 1.0;                // y + 1
    sub.f32 %fnum, %fy, 1.0;                // y - 1
    rcp.approx.f32 %frcpden, %fden;         // 1/(y+1)
    mul.rn.f32 %fres, %fnum, %frcpden;      // (y-1)/(y+1)

    // Saturate for large |x|
    @%p_hi mov.f32 %fres, 1.0;
    @%p_lo mov.f32 %fres, -1.0;

    // Store result
    st.global.f32 [%rd_addr_out], %fres;

    // Next element for this thread
    add.u32 %r_idx, %r_idx, %r_stride;
    bra LOOP;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew expects CUDA tensors.")
        if x.dtype != torch.float32:
            raise RuntimeError("ModelNew expects float32 tensors.")
        out = torch.empty_like(x)
        n = x.numel()
        if n == 0:
            return out

        module = _get_ptx_module()
        block_x = 256
        grid_x = (n + block_x - 1) // block_x

        module.launch(
            "the_entry_name",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, out, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

